
  :root{
    --bg-deep: #14101f; --bg-panel: #1e1830; --bg-panel-2: #241c3a;
    --purple: #8b6bd8; --purple-soft: #6f56b0;
    --gold: #e8b84b; --gold-soft: #f0cc7a;
    --red: #d9556b; --green: #52c78a; --blue: #6fb3e0; --teal: #4bc2ae;
    --text-light: #f3eefc; --text-muted: #a99fc4;
    --border-glow: rgba(139,107,216,0.35);
    --paper: #2a2340; /* dark "paper" replacement for cards */
    /* aliases kept for avatar SVG illustrations (need a light "photo" base) */
    --avatar-bg: #f6efdc; --ink: #2a2340; --line: rgba(35,42,51,0.16); --brass: #a9832f;
  }
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;}
  body{
    background:
      radial-gradient(ellipse at 30% 0%, rgba(139,107,216,0.18), transparent 55%),
      radial-gradient(ellipse at 80% 100%, rgba(232,184,75,0.10), transparent 50%),
      linear-gradient(180deg, #0f0c1a 0%, #14101f 60%, #191330 100%);
    min-height:100vh; font-family:'Nunito', sans-serif; color:var(--text-light);
    display:flex; justify-content:center; padding:20px 14px 60px;
  }
  .game{ width:100%; max-width:960px; }
  /* ===== HALAMAN AWAL: GAMBAR BACKGROUND UTUH ===== */
  body.home-page{
    padding:0;
    min-height:100vh;
    background:#0b0912;
    display:block;
    overflow:hidden;
  }
  body.home-page .game{
    width:100vw;
    max-width:none;
    min-height:100vh;
  }
  body.home-page .topbar,
  body.home-page .backrow,
  body.home-page footer.credit{
    display:none !important;
  }
  body.home-page #app{
    width:100vw;
    height:100vh;
    min-height:0;
    padding:0;
  }
  .home-art{
    position:relative;
    width:100vw;
    height:100vh;
    background-image:url(data:image/png;base64,);
    background-repeat:no-repeat;
    background-position:center center;
    background-size:contain;
    background-color:#0b0912;
  }
  .home-hotspot{
    position:absolute;
    display:block;
    border:0;
    background:transparent;
    padding:0;
    margin:0;
    cursor:pointer;
  }
  .home-hotspot:hover{background:rgba(255,255,255,0.035);border-radius:12px;}
  .home-start{left:3.5%;top:32.0%;width:28.8%;height:10.5%;}
  .home-cases{left:3.5%;top:43.4%;width:28.8%;height:10.5%;}
  .home-notebook{left:3.5%;top:54.8%;width:28.8%;height:10.5%;}
  .home-board{left:3.5%;top:66.2%;width:28.8%;height:10.5%;}
  .home-settings{left:3.5%;top:77.5%;width:28.8%;height:10.5%;}


  .topbar{
    display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px;
    color:var(--text-light); font-family:'Baloo 2', sans-serif;
    padding:10px 16px; letter-spacing:0.2px;
    background:var(--bg-panel); border:1px solid var(--border-glow); border-radius:16px;
    margin-bottom:14px;
  }
  .topbar .title{ font-size:15px; font-weight:700; display:flex; flex-direction:column; line-height:1.5; }
  .topbar .title small{ opacity:0.7; font-size:11px; color:var(--gold-soft); font-weight:600; }
  .topbar-right{ display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
  .hud-badge{
    display:flex; align-items:center; gap:5px; background:var(--bg-panel-2);
    border:1px solid var(--border-glow); border-radius:999px; padding:6px 11px;
    font-size:12px; font-weight:700; font-family:'Baloo 2', sans-serif;
  }
  .hearts{ font-size:13px; letter-spacing:1px; }
  .pill-btn{
    font-family:'Baloo 2', sans-serif; font-weight:600; background:var(--bg-panel-2); color:var(--text-light);
    border:1px solid var(--border-glow); padding:8px 13px; font-size:11px; cursor:pointer; border-radius:999px;
  }
  .pill-btn:hover{ background:var(--purple-soft); }
  .pill-btn.danger{ background:var(--red); color:#fff; border-color:var(--red); }

  .music-toggle{
    position:fixed; right:18px; bottom:18px; z-index:50; display:flex; align-items:center; gap:6px;
    font-family:'Baloo 2', sans-serif; font-weight:700; color:var(--text-light);
    background:rgba(30,24,48,0.94); border:1px solid var(--border-glow); border-radius:999px;
    padding:9px 13px; font-size:12px; cursor:pointer; box-shadow:0 6px 18px rgba(0,0,0,0.35);
  }
  .music-toggle:hover, .music-toggle.playing{ background:var(--purple-soft); }
  .music-toggle.playing{ border-color:var(--gold); }

  .backrow{ display:flex; align-items:center; gap:10px; margin-bottom:14px; }
  .backrow .back-btn{
    font-family:'Baloo 2', sans-serif; font-weight:600; background:var(--bg-panel); border:1px solid var(--border-glow);
    color:var(--text-light); padding:8px 14px; font-size:12px; cursor:pointer; border-radius:999px;
  }
  .backrow .back-btn:hover{ background:var(--purple-soft); }
  .backrow .crumb{ color:var(--text-muted); font-family:'Baloo 2', sans-serif; font-size:11px; }

  .card{
    background:linear-gradient(160deg, var(--bg-panel), var(--bg-panel-2));
    border:1px solid var(--border-glow); border-radius:18px;
    box-shadow:0 14px 34px rgba(0,0,0,0.4); padding:28px 26px; position:relative;
    animation:settle .4s ease;
  }
  @keyframes settle{ from{ opacity:0; transform:translateY(10px);} to{ opacity:1; transform:translateY(0);} }

  .eyebrow{ font-family:'Caveat', cursive; font-weight:700; font-size:22px; color:var(--gold-soft); margin:0 0 2px; }
  h1{ font-family:'Baloo 2', sans-serif; font-weight:700; font-size:25px; margin:0 0 14px; line-height:1.3; color:var(--text-light); }
  h2{ font-family:'Baloo 2', sans-serif; font-weight:700; font-size:17px; margin:0 0 10px; color:var(--text-light); }
  p{ line-height:1.7; margin:0 0 14px; color:var(--text-muted); }
  .lead{ font-style:italic; color:var(--text-light); }

  .btn{
    font-family:'Baloo 2', sans-serif; font-weight:700; background:linear-gradient(135deg, var(--purple), var(--purple-soft));
    color:#fff; border:none; padding:12px 20px; font-size:13px; cursor:pointer; letter-spacing:0.3px;
    border-radius:12px; box-shadow:0 4px 14px rgba(139,107,216,0.35);
  }
  .btn:hover{ background:linear-gradient(135deg, var(--gold), var(--gold-soft)); color:#241c3a; }
  .btn.secondary{ background:transparent; color:var(--text-light); border:1px solid var(--border-glow); box-shadow:none; }
  .btn.secondary:hover{ background:var(--bg-panel-2); color:var(--text-light); }
  .btn:disabled{ opacity:0.35; cursor:not-allowed; }
  .btn-row{ display:flex; gap:10px; flex-wrap:wrap; margin-top:16px; }

  .menu-grid{ display:flex; flex-direction:column; gap:12px; margin:18px 0 4px; }
  .menu-item{
    display:flex; align-items:center; gap:14px;
    padding:16px 18px; border:1px solid var(--border-glow); border-radius:14px;
    font-family:'Baloo 2', sans-serif; font-size:14px; font-weight:700; cursor:pointer;
    background:var(--item-color, var(--bg-panel-2)); transition:transform .15s;
  }
  .menu-item:hover{ transform:translateX(3px); }
  .menu-item .m-icon{
    width:38px; height:38px; border-radius:10px; display:flex; align-items:center; justify-content:center;
    background:rgba(255,255,255,0.14); font-size:18px; flex-shrink:0;
  }
  .menu-item .m-text{ flex:1; }
  .menu-item .m-sub{ font-family:'Nunito',sans-serif; font-weight:600; font-size:11px; opacity:0.75; display:block; margin-top:2px; }
  .menu-item .arrow{ opacity:0.7; }

  .obj-grid{ display:grid; grid-template-columns:1fr 1fr; gap:10px; margin:16px 0 4px; }
  .obj-item{
    border:1px solid var(--border-glow); border-radius:12px; padding:13px 12px; cursor:pointer;
    background:var(--bg-panel-2); transition:background .15s, transform .15s; position:relative;
    display:flex; align-items:center; gap:8px;
  }
  .obj-item:hover{ background:var(--purple-soft); transform:translateY(-2px); }
  .obj-item .label{ font-family:'Baloo 2', sans-serif; font-weight:600; font-size:12px; display:block; }
  .obj-item.done{ border-color:var(--green); box-shadow:0 0 0 1px var(--green) inset; }
  .obj-item.done .label::after{ content:" ✓"; color:var(--green); }

  .clue-popup{
    margin-top:16px; border-left:4px solid var(--gold); background:var(--bg-panel-2); padding:14px 16px;
    border-radius:0 12px 12px 0; animation:settle .35s ease;
  }
  .clue-popup .tag{ font-family:'Caveat', cursive; font-weight:700; color:var(--gold-soft); font-size:19px; display:block; margin-bottom:4px; }

  .notebook-item{
    display:flex; gap:8px; align-items:flex-start; padding:9px 0;
    border-bottom:1px dotted var(--border-glow); font-size:13px; color:var(--text-muted);
  }
  .notebook-item.collected{ color:var(--text-light); }
  .notebook-item .box{ font-family:monospace; flex-shrink:0; color:var(--green); }

  .evidence-card{
    border:1px solid var(--border-glow); border-radius:12px; padding:14px 16px; margin-bottom:10px; background:var(--bg-panel-2);
  }
  .evidence-card .ev-tag{ font-family:'Baloo 2', sans-serif; font-weight:700; font-size:13px; color:var(--gold-soft); }
  .evidence-card .ev-meta{ font-size:11px; color:var(--text-muted); margin-top:3px; }

  .puzzle-box{ background:var(--bg-panel-2); border:1px dashed var(--gold); border-radius:12px; padding:18px 20px; margin:16px 0; }
  .puzzle-sequence{ font-family:'Baloo 2', sans-serif; font-weight:700; font-size:20px; letter-spacing:4px; margin:10px 0 16px; color:var(--gold-soft); }
  .puzzle-box input{
    font-family:'Baloo 2', sans-serif; font-size:16px; padding:10px 12px; width:100px; border-radius:8px;
    border:1px solid var(--border-glow); background:var(--bg-deep); color:var(--text-light);
  }
  .puzzle-msg{ margin-top:10px; font-size:13px; min-height:18px; }
  .puzzle-msg.wrong{ color:var(--red); }
  .puzzle-msg.right{ color:var(--green); }

  .char-list{ display:flex; flex-direction:column; gap:10px; margin:16px 0; }
  .char-row{
    border:1px solid var(--border-glow); border-radius:14px; padding:12px 14px; display:flex; align-items:center; gap:12px;
    cursor:pointer; background:var(--bg-panel-2);
  }
  .char-row:hover{ background:var(--purple-soft); }
  .char-row.read{ border-color:var(--green); }
  .char-info{ flex:1; }
  .char-row .name{ font-family:'Baloo 2', sans-serif; font-weight:700; font-size:13px; }
  .char-row .role{ font-size:11px; color:var(--text-muted); display:block; margin-top:2px; }
  .avatar-icon{ width:46px; height:46px; flex-shrink:0; border-radius:50%; box-shadow:0 2px 8px rgba(0,0,0,0.4); background:var(--bg-deep); }
  .avatar-icon.small{ width:32px; height:32px; }
  .avatar-icon.big{ width:74px; height:74px; }
  .avatar-icon.stage{ width:64px; height:64px; }

  .dialogue-head{ display:flex; align-items:center; gap:14px; margin-bottom:16px; }
  .dialogue-head .who h2{ margin:0; }
  .dialogue-head .who p{ margin:2px 0 0; font-size:12px; }
  .topic-row{ display:flex; flex-direction:column; gap:8px; margin:14px 0; }
  .topic-btn{
    font-family:'Baloo 2', sans-serif; font-weight:600; text-align:left; padding:11px 14px; border-radius:10px;
    background:var(--bg-panel-2); border:1px solid var(--border-glow); cursor:pointer; font-size:12px; color:var(--text-light);
  }
  .topic-btn:hover{ background:var(--purple-soft); }
  .dlog{ display:flex; flex-direction:column; gap:10px; margin:14px 0; }
  .bubble{ padding:12px 14px; background:var(--bg-panel-2); border-left:3px solid var(--gold); border-radius:0 10px 10px 0; font-style:italic; font-size:13px; }
  .bubble.q{ border-left-color:var(--red); font-style:normal; color:var(--text-muted); }

  .suspects{ display:flex; flex-direction:column; gap:10px; margin:16px 0; }
  .suspect-btn{
    font-family:'Baloo 2', sans-serif; font-weight:700; text-align:left; padding:11px 15px; background:var(--bg-panel-2);
    border:1px solid var(--border-glow); border-radius:12px; cursor:pointer; font-size:13px; display:flex; align-items:center; gap:12px; color:var(--text-light);
  }
  .suspect-btn:hover{ background:var(--purple-soft); }

  .ending-badge{ font-family:'Baloo 2', sans-serif; font-weight:700; display:inline-block; padding:6px 14px; margin-bottom:14px; font-size:12px; border-radius:999px; }
  .ending-true{ background:var(--green); color:#0f2818; }
  .ending-incomplete{ background:var(--gold); color:#332204; }
  .ending-wrong{ background:var(--red); color:#330b12; }
  .stars{ font-size:26px; letter-spacing:6px; margin:10px 0 4px; color:var(--gold-soft); }

  .case-row{
    display:flex; align-items:center; gap:14px; padding:14px 16px; border:1px solid var(--border-glow); border-radius:14px;
    background:var(--bg-panel-2); margin-bottom:0; cursor:pointer;
  }
  .case-row.locked{ opacity:0.45; cursor:not-allowed; }
  .case-row.done{ border-color:var(--green); box-shadow:0 0 0 1px var(--green) inset; }
  .case-row .icon{ font-size:22px; }
  .case-row .info{ flex:1; }
  .case-row .cname{ font-family:'Baloo 2', sans-serif; font-weight:700; font-size:13px; display:block; }
  .case-row .cstatus{ font-size:11px; color:var(--text-muted); }
  .connector{ width:1px; height:12px; background:var(--border-glow); margin-left:33px; }

  .board-section{ margin-bottom:20px; }
  .board-avatars{ display:flex; flex-wrap:wrap; gap:14px; margin-top:10px; }
  .board-avatar{ text-align:center; width:64px; }
  .board-avatar .name{ font-size:11px; font-family:'Baloo 2', sans-serif; font-weight:700; margin-top:4px; }

  .backdrop{ position:fixed; inset:0; background:rgba(8,6,16,0.65); z-index:60; display:none; align-items:center; justify-content:center; padding:20px; }
  .backdrop.show{ display:flex; }
  .modal{ background:var(--bg-panel); border:1px solid var(--border-glow); border-radius:16px; box-shadow:0 14px 34px rgba(0,0,0,0.5); padding:26px 24px; max-width:360px; width:100%; }
  .modal h2{ margin-top:0; }

  /* ---- SCENE (Ruang OSIS) ---- */
  .scene-layout{ display:grid; grid-template-columns:220px 1fr; gap:16px; }
  @media (max-width:680px){ .scene-layout{ grid-template-columns:1fr; } }
  .scene-sidebar{ display:flex; flex-direction:column; gap:12px; }
  .side-box{ background:var(--bg-panel-2); border:1px solid var(--border-glow); border-radius:12px; padding:14px 14px; }
  .side-box h3{ font-family:'Baloo 2', sans-serif; font-weight:700; font-size:12px; margin:0 0 8px; color:var(--gold-soft); text-transform:uppercase; letter-spacing:0.5px; }
  .side-box ul{ margin:0; padding-left:16px; font-size:12px; color:var(--text-muted); line-height:1.6; }
  .side-box.tip{ background:linear-gradient(135deg, rgba(232,184,75,0.15), rgba(232,184,75,0.05)); }

  .stage{
    background:
      radial-gradient(ellipse at 50% 0%, rgba(139,107,216,0.15), transparent 60%),
      linear-gradient(180deg, #1a1530 0%, #201936 60%, #17122a 100%);
    border:1px solid var(--border-glow); border-radius:16px; padding:20px; position:relative; overflow:hidden;
  }
  .stage-window{
    position:absolute; top:14px; right:22px; width:90px; height:60px; border-radius:6px;
    background:linear-gradient(180deg, #4a3f78, #2c2450); border:3px solid #362a54; opacity:0.7;
  }
  .stage-title{ font-family:'Baloo 2', sans-serif; font-weight:800; font-size:16px; margin:0 0 12px; text-align:center; letter-spacing:0.5px; }
  .standees{ display:flex; justify-content:center; gap:18px; flex-wrap:wrap; margin-bottom:18px; }
  .standee{ text-align:center; cursor:pointer; position:relative; }
  .standee .bicara{
    font-family:'Baloo 2', sans-serif; font-weight:700; font-size:10px; background:#fff; color:#241c3a;
    border-radius:999px; padding:3px 9px; display:inline-block; margin-bottom:4px; box-shadow:0 2px 6px rgba(0,0,0,0.3);
  }
  .standee .sname{ font-size:11px; font-weight:700; font-family:'Baloo 2', sans-serif; margin-top:4px; }
  .standee .ring{ width:64px; height:8px; border-radius:50%; background:rgba(232,184,75,0.35); margin:3px auto 0; }
  .standee.read .sname{ color:var(--green); }

  .hotspot-grid{ display:flex; flex-wrap:wrap; gap:10px; justify-content:center; }
  .hotspot-chip{
    display:flex; align-items:center; gap:7px; background:rgba(20,16,31,0.75); border:1px solid var(--border-glow);
    border-radius:999px; padding:9px 14px; font-family:'Baloo 2', sans-serif; font-weight:600; font-size:11px;
    cursor:pointer; color:var(--text-light);
  }
  .hotspot-chip:hover{ background:var(--purple-soft); }
  .hotspot-chip.done{ border-color:var(--green); color:var(--green); }

  .loc-tabs{ display:flex; gap:8px; overflow-x:auto; margin-top:16px; padding-bottom:4px; }
  .loc-tab{
    flex-shrink:0; width:88px; text-align:center; padding:10px 6px; border-radius:12px;
    border:1px solid var(--border-glow); background:var(--bg-panel-2); font-family:'Baloo 2', sans-serif; font-weight:700; font-size:10px;
  }
  .loc-tab.active{ border-color:var(--gold); background:var(--purple-soft); }
  .loc-tab.locked{ opacity:0.4; }
  .loc-tab .lt-icon{ font-size:20px; display:block; margin-bottom:4px; }

  footer.credit{ text-align:center; color:var(--text-muted); font-family:'Baloo 2', sans-serif; font-size:11px; margin-top:22px; opacity:0.7; }
